<?php
// Standalone patch file to apply certificate fixes directly to server or codebase
$files = [
    'app/Providers/AppServiceProvider.php' => '',
    'app/Http/Controllers/Admin/EventController.php' => '',
    'app/Http/Controllers/CertificateController.php' => '',
    'resources/views/admin/certificates/certificates_bulk_pdf.blade.php' => '',
    'resources/views/admin/certificates/certificate_pdf.blade.php' => '',
    'resources/views/admin/certificates/certificate_item.blade.php' => '',
    'resources/views/user/events.blade.php' => '',
];

header('Content-Type: text/plain');
echo "=== APPLYING PATCH ===\n\n";

foreach ($files as $file => $b64) {
    $fullPath = __DIR__ . '/' . $file;
    $dir = dirname($fullPath);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    file_put_contents($fullPath, base64_decode($b64));
    echo "[OK] Wrote: {$file}\n";
}

// Clear compiled blade views so new templates take effect immediately
$viewFiles = glob(__DIR__ . '/storage/framework/views/*.php');
$clearedViews = 0;
if ($viewFiles) {
    foreach ($viewFiles as $vf) {
        if (basename($vf) !== '.gitignore') {
            if (@unlink($vf)) {
                $clearedViews++;
            }
        }
    }
}
echo "[OK] Cleared {$clearedViews} compiled view cache file(s).\n";

// Reset OPcache if active
if (function_exists('opcache_reset')) {
    @opcache_reset();
    echo "[OK] OPcache reset successfully.\n";
}

echo "\n=== ALL PATCHES APPLIED SUCCESSFULLY! ===\n";
